const test = require('node:test');
const assert = require('node:assert/strict');
const { preview } = require('../digest/service.cjs');
const { combine } = require('../digest/config.cjs');
test('an explicit recipient list replaces the whole default list', () => {
  assert.equal(preview({recipients:['night']}),'Daily: night');
  assert.equal(preview({recipients:[]}),'Daily: (none)');
  assert.equal(preview({}),'Daily: ops | desk');
  assert.equal(preview({title:'Quiet',recipients:[]}),'Quiet: (none)');
  assert.equal(preview({title:'Weekly',recipients:['a','b']}),'Weekly: a | b');
  const defaults = Object.freeze({title:'Daily',recipients:Object.freeze(['ops','desk'])});
  const override = Object.freeze({recipients:Object.freeze(['night'])});
  const merged = combine(defaults,override);
  assert.deepEqual(merged,{title:'Daily',recipients:['night']});
  assert.notStrictEqual(merged,defaults); assert.notStrictEqual(merged.recipients,override.recipients);
  merged.recipients.push('extra'); assert.deepEqual(override.recipients,['night']);
  const inherited = combine(defaults,{});
  assert.notStrictEqual(inherited.recipients,defaults.recipients);
  inherited.recipients.pop(); assert.deepEqual(defaults.recipients,['ops','desk']);
});

